pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }
    function testRegression_property() public {
        c.seedMarket(100);
        c.getFreeKilo();
        vm.warp(block.timestamp + 100);
        c.collectDrugs(address(0));
        address ceo = 0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26;
        vm.prank(ceo);
        c.DrugDealer();
        uint256 kilosAfter = c.Kilos(address(this));
        assertTrue(kilosAfter == 300 || kilosAfter == 301, "Must be one of the two possibilities");
        assertTrue(kilosAfter == 300, "Kilos after collect should be exactly 300 (reference behavior)");
    }
}
